import { Model } from "./base/Model";
export class Product extends Model {
}
export class AppState extends Model {
    constructor() {
        super(...arguments);
        this.basket = [];
        this.order = {
            payment: 'online',
            address: '',
            email: '',
            phone: '',
            total: 0,
            items: []
        };
        this.formErrors = {};
    }
    clearBasket() {
        this.basket = [];
        this.updateBasket();
    }
    clearOrder() {
        this.order = {
            payment: 'online',
            address: '',
            email: '',
            phone: '',
            total: 0,
            items: []
        };
    }
    setCatalog(items) {
        this.catalog = items.map(item => new Product(item, this.events));
        this.emitChanges('items:changed', { catalog: this.catalog });
    }
    setPreview(item) {
        this.preview = item.id;
        this.emitChanges('preview:changed', item);
    }
    addToBasket(item) {
        if (this.basket.indexOf(item) < 0) {
            this.basket.push(item);
            this.updateBasket();
        }
    }
    removeFromBasket(item) {
        this.basket = this.basket.filter((it) => it != item);
        this.updateBasket();
    }
    updateBasket() {
        this.emitChanges('counter:changed', this.basket);
        this.emitChanges('basket:changed', this.basket);
    }
    setDeliveryField(field, value) {
        this.order[field] = value;
        if (this.validateDelivery()) {
            this.events.emit('delivery:ready', this.order);
        }
    }
    setContactField(field, value) {
        this.order[field] = value;
        if (this.validateContact()) {
            this.events.emit('contact:ready', this.order);
        }
    }
    validateDelivery() {
        const errors = {};
        if (!this.order.address) {
            errors.address = "Необходимо указать адрес";
        }
        this.formErrors = errors;
        this.events.emit('formErrors:change', this.formErrors);
        return Object.keys(errors).length === 0;
    }
    validateContact() {
        const errors = {};
        if (!this.order.email) {
            errors.email = 'Необходимо указать email';
        }
        else if (!this.order.email.includes('@')) {
            errors.email = 'Email должен содержать @';
        }
        if (!this.order.phone) {
            errors.phone = 'Необходимо указать телефон';
        }
        else if (!/^\+7\d{10}$/.test(this.order.phone)) {
            errors.phone = 'Телефон должен начинаться с +7 и содержать 11 цифр';
        }
        this.formErrors = errors;
        this.events.emit('formErrors:change', this.formErrors);
        return Object.keys(errors).length === 0;
    }
}
